    "imageSrcset": "assets/responsive/ai-capex-nasdaq-correction-480.webp 480w, assets/responsive/ai-capex-nasdaq-correction-960.webp 960w, assets/editorial/ai-capex-nasdaq-correction.webp 1920w"
